contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 elapsed) public payable {
        require(true);

        // Ensure the contract is initialized so getDrugsSinceLastCollect can be used meaningfully.
        c.seedMarket{value: 1}(1);

        // Give the test contract a nonzero kilo balance; this also sets lastCollect to block.timestamp.
        c.getFreeKilo();

        uint256 kilos = c.Kilos(address(this));
        require(kilos == c.STARTING_KILOS());

        // Advance the timestamp deterministically (for local testing with block timestamps).
        elapsed = elapsed % (86400 + 1);

        uint256 expectedSeconds = elapsed;
        if (elapsed > 86400) {
            expectedSeconds = 86400;
        }

        uint256 drugsSince = c.getDrugsSinceLastCollect(address(this));
        uint256 expected = expectedSeconds * kilos;

        assert(drugsSince == expected);
    }

    receive() external payable {}
}

