contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);

        c.seedMarket{value: 0}(1);

        uint256 balanceBefore = c.getBalance();
        uint256 claimedBefore = c.claimedDrugs(address(this));

        uint256 drugsBought = c.calculateDrugBuy(amount, balanceBefore);
        uint256 fee = c.devFee(drugsBought);
        uint256 expectedIncrement = drugsBought - fee;

        c.buyDrugs{value: amount}();

        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 balanceAfter = c.getBalance();

        assert(claimedAfter == claimedBefore + expectedIncrement && balanceAfter >= balanceBefore + amount - c.devFee(amount));
    }

    receive() external payable {}
}

