contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedDrugs, uint256 waitTime) public payable {
        require(address(this).balance >= 0);

        // Initialize the market with the provided seed amount, and give the test contract some kilos so it has drugs to sell.
        c.seedMarket{value: 0}(seedDrugs);
        c.getFreeKilo();

        // Let time pass so the test contract accrues drugs.
        if (waitTime > 0) {
            // The contract's getDrugsSinceLastCollect uses block.timestamp; we cannot fast-forward in a test,
            // but we can still exercise the sellDrugs path. If no time passes, hasDrugs may be zero.
        }

        uint256 hasDrugs = c.getMyDrugs();
        uint256 drugValue = c.calculateDrugSell(hasDrugs);
        uint256 fee = c.devFee(drugValue);
        uint256 marketBefore = c.marketDrugs();

        c.sellDrugs();

        uint256 marketAfter = c.marketDrugs();
        uint256 sellerBalanceAfter = address(this).balance;

        // General rule: the seller receives exactly the calculated net proceeds (drugValue - fee),
        // and marketDrugs increases by exactly hasDrugs.
        assert(marketAfter == marketBefore + hasDrugs);
        assert(sellerBalanceAfter >= drugValue - fee);
    }

    receive() external payable {}
}

